import React from "react";

function SlotCard({ slot }) {
  return (
    <div style={styles.card}>
      <h3>Slot {slot.slot_number}</h3>

      <p><strong>Status:</strong> {slot.status ? "occupied" : "vacant"}</p>

      <p><strong>Last Plate:</strong> {slot.last_plate || "-"}</p>

      <p><strong>Time:</strong> {slot.timestamp || "-"}</p>
    </div>
  );
}

const styles = {
  card: {
    border: "1px solid #ccc",
    padding: "16px",
    borderRadius: "10px",
    width: "250px",
    background: "white",
    marginBottom: "16px",
  },
};

export default SlotCard;
